"""Счета на оплату (вкладка «Счета»): счёт за месяц по подразделению, сбор накладных и строк, номер, печать,
правка, повторно накладную не берёт, архив, на журнал/контракт не влияет. Значки закупки в журнале. Телефон."""
import asyncio, os, json, urllib.request, datetime
from playwright.async_api import async_playwright
fails=[]
def ok(c,m): print(('OK  ' if c else 'FAIL'),m); (None if c else fails.append(m))
def rows(sheet):
    d=json.load(urllib.request.urlopen('http://localhost:8787/dump')).get(sheet) or [[]]; h=d[0]; return [dict(zip(h,r)) for r in d[1:] if any(str(x) for x in r)]
SHOT=os.environ.get('SHOTS','/tmp')
TAB="(t=>{document.querySelector('nav.tabs button[data-tab=\"doc\"]').click(); document.querySelector('nav.tabs button[data-tab=\"'+t+'\"]').click()})"
t=datetime.date.today(); pm_end=t.replace(day=1)-datetime.timedelta(days=1); pm=pm_end.replace(day=1)
D1=(pm+datetime.timedelta(days=4)).isoformat(); D2=(pm+datetime.timedelta(days=14)).isoformat(); D3=t.isoformat()
async def login(b, vw):
    ctx=await b.new_context(viewport={'width':vw[0],'height':vw[1]}); pg=await ctx.new_page(); errs=[]; pg.on('pageerror',lambda e:errs.append(str(e)))
    pg.on('dialog', lambda d: asyncio.ensure_future(d.accept()))
    await pg.goto('http://localhost:8787/page'); await pg.click('#fd-who [data-who="Даниил"]'); await pg.fill('#fd-pass','1111'); await pg.click('#fd-enter'); await pg.wait_for_timeout(2500)
    return ctx, pg, errs
async def mkdoc(pg, jid, date, br, lines):
    ls=','.join(f"{{productId:'{a}',qty:'{q}',price:'{p}'}}" for a,q,p in lines)
    await pg.evaluate(f"(()=>{{const D=__fd.D(); Object.assign(D.draft,{{id:'{jid}', customerId:window.__cid, branchId:'{br}', number:'', date:'{date}', lines:[{ls}]}}); }})()")
    await pg.evaluate(TAB+"('doc')"); await pg.wait_for_timeout(300); await pg.click('#d-save'); await pg.wait_for_timeout(1300)
async def main():
    async with async_playwright() as p:
        b=await p.chromium.launch(executable_path=os.environ.get("BROWSER_EXECUTABLE_PATH"))
        ctx,pg,errs=await login(b,(1300,900))
        ok(await pg.locator('nav.tabs button[data-tab="invoices"]').count()==0, 'отдельной вкладки «Счета» нет')
        await pg.evaluate(TAB+"('doc')"); await pg.wait_for_timeout(300); ok(await pg.is_visible('#inv-dc #inv-new2') and await pg.is_visible('#inv-dc #inv-all'), 'в «Новом документе» — блок «Отдельный счёт» с кнопками')
        await pg.evaluate("""(()=>{const D=__fd.D(), c=D.customers[0]; window.__cid=c.id; c.branches=JSON.stringify([{id:'opA',label:'ОП «Столовые диетического питания»',kpp:'772945024'},{id:'opB',label:'ОП «Комбинат питания»',kpp:'772945025'}]);
          D.prices[c.id]=D.prices[c.id]||{}; [['p-ap','Яблоки','100'],['p-gr','Груши','150']].forEach(([id,n,pr])=>{ D.products.push({id, name:n, code:'', unit:'кг', country:'', price:pr}); D.prices[c.id][id]=pr; }); })()""")
        await mkdoc(pg,'iv1',D1,'opA',[('p-ap','10','100'),('p-gr','4','150')])
        await mkdoc(pg,'iv2',D2,'opA',[('p-ap','5','100')])
        await mkdoc(pg,'iv3',D2,'opB',[('p-ap','7','100')])
        await mkdoc(pg,'iv4',D3,'opA',[('p-gr','2','150')])
        jn=len(rows('Журнал'))
        await pg.evaluate(TAB+"('doc')"); await pg.click('#inv-all'); await pg.wait_for_timeout(500)
        ok('Счетов пока нет' in (await pg.text_content('#inv-list')), 'пустой список с подсказкой')
        await pg.click('#inv-new'); await pg.wait_for_timeout(400)
        await pg.select_option('#inv-dlg select[data-f="customerId"]', await pg.evaluate("window.__cid")); await pg.wait_for_timeout(250)
        await pg.select_option('#inv-dlg select[data-f="branchId"]', 'opA'); await pg.wait_for_timeout(250)
        await pg.click('#inv-dlg .invper [data-invm]:nth-child(1)'); await pg.wait_for_timeout(250)
        docs=await pg.evaluate("[...document.querySelectorAll('#inv-dlg [data-invd]')].map(x=>[x.dataset.invd,x.checked])")
        ok(sorted(docs)==[['iv1',True],['iv2',True]], f'за прошлый месяц по ОП «Столовые» — 2 накладные, обе выбраны: {docs}')
        L=await pg.evaluate("__inv.st().lines.map(x=>[x.name,x.qty,x.price])")
        ok(L==[['Яблоки','15','100'],['Груши','4','150']], f'строки по товарам: яблоки 10+5 = 15 кг, груши 4: {L}')
        tot=(await pg.text_content('#inv-tot')).replace(' ',' '); ok('2 100,00' in tot, f'итого 2 100 = сумма двух накладных: {tot}')
        ok(await pg.input_value('#inv-dlg [data-f="number"]')=='1', 'номер счёта — 1 (своя серия у поставщика)')
        await pg.screenshot(path=f'{SHOT}/inv-form.png')
        await pg.click('#inv-dlg [data-invsave="1"]'); await pg.wait_for_timeout(900)
        ok(await pg.is_visible('#pv'), 'после «Сохранить и открыть счёт» — просмотр счёта')
        pv=(await pg.text_content('#pv-pages')).replace(' ',' ')
        ok('Счёт на оплату № 1' in pv and '772945024' in pv and '2 100,00' in pv, 'в счёте № 1, КПП подразделения и сумма 2 100,00')
        await pg.screenshot(path=f'{SHOT}/inv-pv.png')
        await pg.evaluate("document.querySelector('#pv-close')?document.querySelector('#pv-close').click():null"); await pg.keyboard.press('Escape'); await pg.wait_for_timeout(400)
        await pg.evaluate('__fd.flush()'); await pg.wait_for_timeout(1500)
        R=rows('Счета на оплату'); ok(len(R)==1 and R[0]['Сумма']=='2100' and 'Столовые' in R[0]['Подразделение / точка'] and R[0]['№']=='1', f'в таблице лист «Счета на оплату»: {[(r["№"],r["Сумма"],r["Подразделение / точка"],r["Период"]) for r in R]}')
        ok(len(rows('Журнал'))==jn, 'журнал не изменился — счёт не накладная')
        # второй счёт на тот же месяц и ОП — накладные уже в счёте
        await pg.evaluate(TAB+"('doc')"); await pg.wait_for_timeout(300)
        ok(await pg.locator('#inv-dc .invr').count()==1 and '1' in (await pg.text_content('#inv-all')), 'в «Новом документе» видно последний счёт и «Все счета 1»')
        await pg.click('#inv-all'); await pg.wait_for_timeout(500)
        ok(await pg.locator('#inv-list .invr').count()==1, 'счёт появился в списке')
        await pg.click('#inv-new'); await pg.wait_for_timeout(300)
        await pg.select_option('#inv-dlg select[data-f="customerId"]', await pg.evaluate("window.__cid")); await pg.select_option('#inv-dlg select[data-f="branchId"]', 'opA'); await pg.click('#inv-dlg .invper [data-invm]:nth-child(1)'); await pg.wait_for_timeout(250)
        docs=await pg.evaluate("[...document.querySelectorAll('#inv-dlg [data-invd]')].map(x=>x.checked)")
        ok(docs==[False,False] and 'уже в счёте № 1' in (await pg.text_content('#inv-dlg .invdl')), 'накладные из счёта № 1 второй раз не выбираются сами, видно «уже в счёте № 1»')
        ok(await pg.input_value('#inv-dlg [data-f="number"]')=='2', 'следующий номер — 2')
        # ручной счёт без накладных: по накладным → ручная строка
        await pg.select_option('#inv-dlg select[data-f="branchId"]', 'opB'); await pg.wait_for_timeout(250)
        await pg.click('#inv-dlg [data-invmode="docs"]'); await pg.wait_for_timeout(200)
        L=await pg.evaluate("__inv.st().lines.map(x=>x.name)"); ok(len(L)==1 and 'накладной №' in L[0], f'«По накладным» — одна строка на накладную: {L}')
        await pg.click('#inv-dlg [data-invadd]'); await pg.wait_for_timeout(200)
        ok(await pg.evaluate("document.activeElement.dataset.k==='name'"), 'новая строка — курсор в названии')
        await pg.keyboard.type('Доставка'); await pg.fill('#inv-dlg .invln[data-i="1"] [data-k="price"]','500'); await pg.wait_for_timeout(150)
        tot=(await pg.text_content('#inv-tot')).replace(' ',' '); ok('1 200,00' in tot, f'итого 700 + 500 = 1 200: {tot}')
        await pg.click('#inv-dlg [data-invsave="0"]'); await pg.wait_for_timeout(700)
        ok(await pg.locator('#inv-list .invr').count()==2, 'второй счёт сохранён')
        # правка первого счёта
        first=await pg.evaluate("__inv.rows().find(r=>r.number==='1').id")
        await pg.click(f'#inv-list [data-inve="{first}"]'); await pg.wait_for_timeout(300)
        await pg.fill('#inv-dlg .invln[data-i="0"] [data-k="price"]','110'); await pg.wait_for_timeout(100)
        ok(await pg.locator('#inv-dlg [data-invrb]').count()==1, 'после ручной правки строк — кнопка «Пересобрать из накладных»')
        await pg.click('#inv-dlg [data-invsave="0"]'); await pg.wait_for_timeout(500)
        r=await pg.evaluate(f"__inv.rows().find(r=>r.id==='{first}')"); ok(r['sum']=='2250', f'сумма пересчитана: 15×110 + 4×150 = 2 250 → {r["sum"]}')
        await pg.click(f'#inv-list [data-inv="{first}"]'); await pg.wait_for_timeout(400)
        hist=await pg.text_content('#fd-dcard .dc-hist'); ok('2 100,00' in hist.replace(' ',' ') and '2 250,00' in hist.replace(' ',' '), 'в истории счёта: сумма 2 100 → 2 250')
        await pg.screenshot(path=f'{SHOT}/inv-card.png')
        await pg.click('#fd-dcard [data-dc="arch"]'); await pg.wait_for_timeout(500)
        ok(await pg.locator('#inv-list .invr').count()==1, 'в архив — вернулись в список, счёт из него пропал')
        await pg.check('#inv-arch'); await pg.wait_for_timeout(200); ok(await pg.locator('#inv-list .invr').count()==1, '«Архив» показывает его')
        await pg.uncheck('#inv-arch')
        await pg.fill('#inv-q','доставка'); await pg.wait_for_timeout(200); ok(await pg.locator('#inv-list .invr').count()==1, 'поиск по строке счёта')
        await pg.fill('#inv-q','')
        await pg.screenshot(path=f'{SHOT}/inv-list.png')
        await pg.click('#fd-dcard .dc-x'); await pg.wait_for_timeout(400)
        # значки закупки в журнале
        await pg.evaluate(TAB+"('journal')"); await pg.wait_for_timeout(1500)
        cls=await pg.evaluate("[...document.querySelectorAll('#jr-body [data-zkj=\"iv1\"]')].map(x=>x.className)")
        ok(cls and 'none' in cls[0], f'накладная без закупки — красный значок: {cls}')
        await pg.click('#jr-body [data-zkj="iv1"]'); await pg.wait_for_timeout(1200)
        ok(await pg.locator('#fd-dcard #dc-zk.open').count()==1, 'клик по значку открывает окно сразу с блоком закупки')
        await pg.fill('#dc-zki .dzc[data-pid="p-ap"]','60'); await pg.click('#dc-zki [data-zkc="save"]'); await pg.wait_for_timeout(500)
        await pg.evaluate("document.querySelector('#fd-dcard [data-dc=\"close\"]').click()"); await pg.wait_for_timeout(400)
        cls=await pg.evaluate("document.querySelector('#jr-body [data-zkj=\"iv1\"]').className"); tip=await pg.get_attribute('#jr-body [data-zkj="iv1"]','title')
        ok('part' in cls and '1 из 2' in tip, f'заполнена 1 из 2 — жёлтый: {cls} / {tip}')
        await pg.evaluate("document.querySelector('#jr-body [data-card=\"iv1\"]').click()"); await pg.wait_for_timeout(500); await pg.click('#fd-dcard [data-zkc="toggle"]'); await pg.wait_for_timeout(700)
        await pg.fill('#dc-zki .dzc[data-pid="p-gr"]','90'); await pg.click('#dc-zki [data-zkc="save"]'); await pg.wait_for_timeout(500)
        await pg.evaluate("document.querySelector('#fd-dcard [data-dc=\"close\"]').click()"); await pg.wait_for_timeout(400)
        cls=await pg.evaluate("document.querySelector('#jr-body [data-zkj=\"iv1\"]').className"); ok('ok' in cls, f'всё заполнено — зелёный: {cls}')
        await pg.evaluate("document.querySelector('#jr-body [data-card=\"iv1\"]').click()"); await pg.wait_for_timeout(500); await pg.click('#fd-dcard [data-zkc="toggle"]'); await pg.wait_for_timeout(700)
        await pg.fill('#dc-zki .dzc[data-pid="p-gr"]','190'); await pg.click('#dc-zki [data-zkc="save"]'); await pg.wait_for_timeout(500)
        await pg.evaluate("document.querySelector('#fd-dcard [data-dc=\"close\"]').click()"); await pg.wait_for_timeout(400)
        cls=await pg.evaluate("document.querySelector('#jr-body [data-zkj=\"iv1\"]').className"); tip=await pg.get_attribute('#jr-body [data-zkj="iv1"]','title')
        ok('part' in cls and 'дороже продажи' in tip, f'закупка дороже продажи — жёлтый с пояснением: {tip}')
        await pg.locator('#jr-body').screenshot(path=f'{SHOT}/inv-journal.png')
        lbl=await pg.text_content('#jr-body [data-zkj="iv1"]'); ok(lbl.strip()=='!', f'подпись на плашке: все цены есть, но есть замечание — «!»: {lbl}')
        box=await pg.evaluate("(()=>{const b=document.querySelector('#jr-body [data-zkj=\"iv1\"]').getBoundingClientRect(); return [b.width,b.height]})()"); ok(box[0]>=56 and box[1]>=24, f'плашка крупная, легко попасть: {box}')
        await pg.set_viewport_size({'width':390,'height':844}); await pg.wait_for_timeout(400)
        await pg.locator('#jr-body').screenshot(path=f'{SHOT}/inv-journal-phone.png')
        sw=await pg.evaluate("document.documentElement.scrollWidth"); ok(sw<=390, f'журнал на телефоне без прокрутки вбок ({sw})')
        await pg.click('#jr-body [data-zkj="iv1"]'); await pg.wait_for_timeout(1200); ok(await pg.locator('#fd-dcard #dc-zk.open').count()==1, 'на телефоне нажатие на плашку открывает закупку')
        ok(not errs, f'ошибок нет {errs[:2]}'); await ctx.close()
        # Наталья видит счета, Гриша — нет
        for who,pw,see in [('Наталья','2222',True),('Гриша','3333',False)]:
            ctx=await b.new_context(viewport={'width':1300,'height':900}); pg=await ctx.new_page()
            await pg.goto('http://localhost:8787/page'); await pg.click(f'#fd-who [data-who="{who}"]'); await pg.fill('#fd-pass',pw); await pg.click('#fd-enter'); await pg.wait_for_timeout(2500)
            await pg.evaluate(TAB+"('doc')"); await pg.wait_for_timeout(300); v=await pg.is_visible('#inv-dc'); ok(v==see, f'{who}: блок «Отдельный счёт» {"виден" if see else "скрыт"}')
            await ctx.close()
        ctx,pg,errs=await login(b,(390,844)); await pg.evaluate(TAB+"('doc')"); await pg.wait_for_timeout(400); await pg.evaluate("document.querySelector('#inv-dc').scrollIntoView()"); await pg.screenshot(path=f'{SHOT}/inv-dc-phone.png'); await pg.click('#inv-all'); await pg.wait_for_timeout(600)
        sw=await pg.evaluate("document.documentElement.scrollWidth"); ok(sw<=390, f'телефон: список без прокрутки вбок ({sw})')
        await pg.screenshot(path=f'{SHOT}/inv-phone.png')
        await pg.click('#inv-new'); await pg.wait_for_timeout(400); await pg.select_option('#inv-dlg select[data-f="customerId"]', index=1); await pg.wait_for_timeout(300)
        sw=await pg.evaluate("document.documentElement.scrollWidth"); ok(sw<=390, f'телефон: форма счёта без прокрутки вбок ({sw})')
        await pg.screenshot(path=f'{SHOT}/inv-phone-form.png'); ok(not errs, f'телефон: ошибок нет {errs[:2]}')
        await b.close()
    print('ИТОГ:', 'всё прошло' if not fails else f'ошибок {len(fails)}')
asyncio.run(main())
